import request from 'supertest';
import app from '../../../../server.js';
import bcrypt from 'bcryptjs';
import User from '../../../models/usersModels.js';

let token;

beforeAll(async () => {
    const hashedPassword = await bcrypt.hash("123", 10);
    await User.destroy({ where: { email: "saralamari11@teste.com" } });
    await User.create({
        email: "saralamari11@teste.com",
        password: hashedPassword
    });

    const res = await request(app)
        .put('/users/signin')
        .send({ email: 'saralamari11@teste.com', password: '123' });
    token = res.body.token;
});

afterAll(async () => {
    await User.destroy({ where: { email: 'saralamari11@teste.com' } });
});

describe('Teste do endpoint /tts/describeImage', () => {
    it('Deve retornar uma descrição da imagem', async () => {
        const res = await request(app)
            .post('/tts/describeImage')
            .set('Authorization', `Bearer ${token}`)
            .send({ imageBase64: ""});

        expect(res.status).toBe(200);
        expect(res.body).toHaveProperty('description');
    }, 15000);

    it('Deve retornar 400 se eu não enviar a imagem', async () => {
        const res = await request(app)
            .post('/tts/describeImage')
            .set('Authorization', `Bearer ${token}`)
            .send({imageBase64: null})

        expect(res.status).toBe(400);
        expect(res.body.error).toBe('A imagem é obrigatória');
    });
});
